code.cpp:
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int maxVal = nums[0];
        for (int x : nums) {
            if (x > maxVal) maxVal = x;
        }
        int n = nums.size();
        int left = 0;
        int count = 0;
        long long result = 0;
        for (int right = 0; right < n; right++) {
            if (nums[right] == maxVal) {
                count++;
            }
            while (count >= k) {
                if (nums[left] == maxVal) {
                    count--;
                }
                left++;
            }
            result += left;
        }
        return result;
    }
};
